@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>
<p class="text-muted">Fill out the form below to request enrollment in a course.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@selectedCourseTitle</strong> has been received. You will receive a confirmation at <strong>@Model.Email</strong>.</p>
        <hr />
        <a href="/enroll" class="btn btn-outline-success">Submit Another Request</a>
        <a href="/courses" class="btn btn-outline-secondary ms-2">Browse Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" id="studentName" name="Model.StudentName" value="@Model.StudentName" required />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" id="studentId" name="Model.StudentId" value="@Model.StudentId" placeholder="e.g., CS12345" required />
                    <div class="form-text">1–3 uppercase letters followed by 5–9 digits.</div>
                </div>

                <div class="mb-3">
                    <label for="email" class="form-label">Email Address <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" id="email" name="Model.Email" value="@Model.Email" required />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                    <select class="form-select" id="courseId" name="Model.CourseId" required>
                        <option value="">— Select a course —</option>
                        @foreach (var course in courses)
                        {
                            var dept = Catalog.GetDepartment(course.DepartmentId);
                            if (course.Id == Model.CourseId)
                            {
                                <option value="@course.Id" selected>@course.CourseCode — @course.Title (@dept?.Code)</option>
                            }
                            else
                            {
                                <option value="@course.Id">@course.CourseCode — @course.Title (@dept?.Code)</option>
                            }
                        }
                    </select>
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </form>
        </div>

        <div class="col-lg-4">
            <div class="card bg-light">
                <div class="card-body">
                    <h5 class="card-title">Need Help?</h5>
                    <p class="card-text">Contact the Registrar's Office for assistance with enrollment.</p>
                    <p class="mb-1"><strong>Email:</strong> registrar@university.edu</p>
                    <p class="mb-0"><strong>Phone:</strong> (555) 123-4567</p>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    private List<Course> courses = [];
    private bool submitted;
    private string selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();

        if (PreselectedCourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = PreselectedCourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(Model.CourseId);
        selectedCourseTitle = course is not null ? $"{course.CourseCode} — {course.Title}" : "Unknown";
        Catalog.SubmitEnrollmentRequest(Model);
        submitted = true;
    }
}

